host.querySelectorAll("[data-tr-region]").forEach(btn=>btn.addEventListener("click",()=>{S.region=btn.getAttribute("data-tr-region")||"Lombardia";writeTrend();render();scheduleTrendSimulation();}));
document.getElementById("trApplyMechanical").addEventListener("click",()=>{const p=getParties();Object.keys(p).forEach(id=>{S.manual[S.region]??={};S.manual[S.region][id]=mechanicalScenario(S.chamber,S.region,id,S.coefficient);});writeTrend();render();scheduleTrendSimulation();});
document.getElementById("trCopy2022").addEventListener("click",()=>{const p=getParties();S.manual[S.region]??={};Object.keys(p).forEach(id=>{const v=getHistorical(S.chamber,S.region,2022,id);if(v!=null)S.manual[S.region][id]=v;});writeTrend();render();scheduleTrendSimulation();});
document.getElementById("trResetRegion").addEventListener("click",()=>{const p=getParties();S.manual[S.region]??={};Object.keys(p).forEach(id=>{S.manual[S.region][id]=p[id][S.chamber==="camera"?"camera":"senate"];});S.results=null;writeTrend();render();scheduleTrendSimulation();});
